const JEE_DAY1_TOPIC_PACK = [
[{"id":"P1-01","s":"Physics","c":"Electrostatics","t":"mcq","q":"At a distance r from a point charge, the electric field is E. What is the field at distance 2r?","o":["E/2","E/4","2E","4E"],"a":1,"e":"For a point charge, E=k|q|/r². Replacing r by 2r gives E/4.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-02","s":"Physics","c":"Electrostatics","t":"mcq","q":"Two equal positive point charges +q are separated by distance d. The net electric field at their midpoint is:","o":["2kq/d²","4kq/d²","zero","kq/d²"],"a":2,"e":"The two fields at the midpoint have equal magnitudes and opposite directions, so they cancel.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-03","s":"Physics","c":"Electrostatics","t":"mcq","q":"A point charge +q is at the centre of a spherical Gaussian surface. The total electric flux through the sphere is:","o":["q/(2ε₀)","q/ε₀","2q/ε₀","zero"],"a":1,"e":"Gauss’s law gives Φ=Qenclosed/ε₀=q/ε₀.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-04","s":"Physics","c":"Electrostatics","t":"mcq","q":"A point charge q is placed at one vertex of a cube. The electric flux through that cube is:","o":["q/ε₀","q/(2ε₀)","q/(4ε₀)","q/(8ε₀)"],"a":3,"e":"Eight identical cubes can be arranged around the vertex to form a larger cube with the charge at its centre. Each small cube gets one-eighth of q/ε₀.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-05","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric field at distance r from a very long straight wire with uniform linear charge density λ is:","o":["λ/(4πε₀r)","λ/(2πε₀r)","λr/(2πε₀)","2λ/(πε₀r)"],"a":1,"e":"Using a cylindrical Gaussian surface, E(2πrL)=λL/ε₀, hence E=λ/(2πε₀r).","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-06","s":"Physics","c":"Electrostatics","t":"mcq","q":"The magnitude of the electric field due to a large uniformly charged non-conducting plane sheet is:","o":["σ/ε₀","σ/(2ε₀)","2σ/ε₀","zero"],"a":1,"e":"A pillbox Gaussian surface gives 2EA=σA/ε₀, so E=σ/(2ε₀) on either side.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-07","s":"Physics","c":"Electrostatics","t":"mcq","q":"Inside the material of a conductor in electrostatic equilibrium, the electric field is:","o":["maximum","σ/ε₀","zero","dependent on its shape"],"a":2,"e":"Free charges rearrange until the electric field inside the conducting material is zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-08","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric potential everywhere inside a charged thin spherical conducting shell of radius R is:","o":["zero everywhere","kQ/r","constant and equal to kQ/R","infinite"],"a":2,"e":"The field inside the shell is zero, so potential is constant; continuity at the surface gives V=kQ/R.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-09","s":"Physics","c":"Electrostatics","t":"mcq","q":"A dipole of moment p is placed in a uniform electric field E at angle θ. The magnitude of its torque is:","o":["pE cosθ","pE sinθ","pE tanθ","p/E"],"a":1,"e":"The torque magnitude is τ=pE sinθ.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-10","s":"Physics","c":"Electrostatics","t":"mcq","q":"The potential energy of an electric dipole in a uniform field is minimum when the angle between p and E is:","o":["0°","90°","180°","45°"],"a":0,"e":"U=−pE cosθ is minimum at cosθ=1, i.e. θ=0°.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-11","s":"Physics","c":"Electrostatics","t":"mcq","q":"For a short dipole at the same large distance r, the ratio of axial field magnitude to equatorial field magnitude is:","o":["1/2","1","2","4"],"a":2,"e":"At large r, Eaxial=2kp/r³ and Eequatorial=kp/r³, so the ratio is 2.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-12","s":"Physics","c":"Electrostatics","t":"mcq","q":"Charges +q and +4q are separated by distance d. The zero-field point between them is at a distance from +q equal to:","o":["d/2","d/3","2d/3","d/4"],"a":1,"e":"Set kq/x²=4kq/(d−x)². Taking positive roots gives d−x=2x, hence x=d/3.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-13","s":"Physics","c":"Electrostatics","t":"mcq","q":"Charges +q and −4q are separated by distance d. Where on the line is the electric field zero?","o":["At d/3 from +q between the charges","At d to the left of +q","At d to the right of −4q","At the midpoint"],"a":1,"e":"For unlike unequal charges the zero-field point lies outside, on the side of the smaller charge. Equating q/x²=4/(d−x)² for x<0 gives x=−d.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-14","s":"Physics","c":"Electrostatics","t":"mcq","q":"If the separation between two point charges is doubled, the magnitude of their Coulomb force becomes:","o":["twice","half","one-fourth","four times"],"a":2,"e":"Coulomb force varies inversely as the square of separation.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-15","s":"Physics","c":"Electrostatics","t":"mcq","q":"Two charges interact with force F in vacuum. If the same charges are placed at the same separation in a medium of dielectric constant K, the force is:","o":["KF","F/K","F/K²","F"],"a":1,"e":"The electrostatic force in a uniform dielectric medium is reduced by the factor K.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-16","s":"Physics","c":"Electrostatics","t":"mcq","q":"A positive test charge q is placed in an electric field E. The force on it is:","o":["qE in the direction of E","qE opposite to E","E/q in the direction of E","zero"],"a":0,"e":"By definition, the electric field is force per unit positive test charge: F=qE.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-17","s":"Physics","c":"Electrostatics","t":"mcq","q":"A charge of 2 μC moves through a potential drop of 3 V. The work done by the electric field is:","o":["1.5 μJ","3 μJ","6 μJ","12 μJ"],"a":2,"e":"Work done by the field for a drop ΔV is qΔV=2×10⁻⁶×3=6×10⁻⁶ J.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-18","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric potential due to a point charge Q at distance r, taking zero potential at infinity, is:","o":["kQ/r²","kQ/r","kQr","kQ"],"a":1,"e":"The potential of a point charge is V=kQ/r.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-19","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric potential energy of two point charges +q and +q separated by r is:","o":["−kq²/r","zero","kq²/r","2kq²/r"],"a":2,"e":"The interaction energy is U=kq₁q₂/r; for two positive charges it is positive.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-20","s":"Physics","c":"Electrostatics","t":"mcq","q":"A uniformly charged thin ring has total charge Q and radius R. Its electric field at the centre is:","o":["kQ/R²","kQ/R","zero","infinite"],"a":2,"e":"Symmetry makes the field contributions from opposite ring elements cancel at the centre.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-21","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric field on the axis of a uniformly charged ring at distance x from its centre is:","o":["kQ/(x²+R²)","kQx/(x²+R²)^(3/2)","kQ/(x²+R²)^(3/2)","kQx²/(x²+R²)"],"a":1,"e":"Transverse components cancel by symmetry; the axial component integrates to E=kQx/(x²+R²)^(3/2).","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-22","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric potential on the axis of a charged ring (charge Q, radius R), at distance x from its centre, is:","o":["kQ/√(x²+R²)","kQx/(x²+R²)","kQ/(x²+R²)","zero"],"a":0,"e":"Every ring element is at the same distance √(x²+R²), so V=kQ/√(x²+R²).","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-23","s":"Physics","c":"Electrostatics","t":"mcq","q":"A uniformly charged non-conducting solid sphere has surface field Eₛ. Its field at r=R/2 is:","o":["Eₛ/4","Eₛ/2","2Eₛ","Eₛ"],"a":1,"e":"Inside a uniformly charged solid sphere, E∝r. At R/2 the field is half its surface value.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-24","s":"Physics","c":"Electrostatics","t":"mcq","q":"The magnitude of the field just outside the surface of a charged conductor with surface charge density σ is:","o":["σ/(2ε₀)","σ/ε₀","2σ/ε₀","zero"],"a":1,"e":"A Gaussian pillbox across the conductor surface gives E=σ/ε₀ just outside, with zero field inside.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-25","s":"Physics","c":"Electrostatics","t":"mcq","q":"Two very large parallel sheets carry equal and opposite surface charge densities +σ and −σ. The field between them is:","o":["zero","σ/(2ε₀)","σ/ε₀","2σ/ε₀"],"a":2,"e":"The fields from the sheets add between them: σ/(2ε₀)+σ/(2ε₀)=σ/ε₀.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-26","s":"Physics","c":"Electrostatics","t":"mcq","q":"A closed Gaussian surface encloses charges +3q and −q. Its total electric flux is:","o":["q/ε₀","2q/ε₀","3q/ε₀","4q/ε₀"],"a":1,"e":"Only the net enclosed charge matters: Φ=(3q−q)/ε₀=2q/ε₀.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-27","s":"Physics","c":"Electrostatics","t":"mcq","q":"A charge outside a closed Gaussian surface contributes what amount to the net flux through that surface?","o":["q/ε₀","−q/ε₀","zero","A value depending on distance"],"a":2,"e":"An external charge creates field through the surface but has zero net contribution to total closed-surface flux.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-28","s":"Physics","c":"Electrostatics","t":"mcq","q":"Gauss’s law for a closed surface is valid:","o":["only for spherical surfaces","only for symmetric charge distributions","for every closed surface","only in vacuum outside charges"],"a":2,"e":"Gauss’s law is universally valid for any closed surface; symmetry is only needed to use it easily to calculate E.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-29","s":"Physics","c":"Electrostatics","t":"mcq","q":"At the midpoint of an electric dipole (+q and −q separated by 2a), the electric field direction is:","o":["from −q to +q","from +q to −q","perpendicular to the dipole axis","zero"],"a":1,"e":"At the midpoint, the field due to +q points away from +q and the field due to −q points toward −q; both point from + to −.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-30","s":"Physics","c":"Electrostatics","t":"mcq","q":"At every point on the perpendicular bisector of an ideal electric dipole, the electric potential is:","o":["positive","negative","zero","infinite"],"a":2,"e":"The point is equidistant from +q and −q, so their scalar potentials cancel.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-31","s":"Physics","c":"Electrostatics","t":"mcq","q":"Electrostatic shielding by a closed conductor works because the electric field inside the conducting material is:","o":["constant but non-zero","zero","infinite","equal to the external field"],"a":1,"e":"In electrostatic equilibrium the conductor rearranges charge so that the field in its material vanishes; a closed conducting enclosure shields its cavity from external static fields.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-32","s":"Physics","c":"Electrostatics","t":"mcq","q":"For a conductor with a sharp pointed region, the surface charge density and field near the point are generally:","o":["smaller","larger","zero","uniform everywhere"],"a":1,"e":"Charge accumulates more densely at regions of high curvature; the surface field is correspondingly stronger.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-33","s":"Physics","c":"Electrostatics","t":"mcq","q":"A charged conducting sphere has radius R and surface field Eₛ. The field at distance 2R from its centre is:","o":["Eₛ/2","Eₛ/4","2Eₛ","4Eₛ"],"a":1,"e":"Outside a spherical conductor E∝1/r². At 2R, E=Eₛ/4.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-34","s":"Physics","c":"Electrostatics","t":"mcq","q":"A charged conducting sphere has radius R and surface potential Vₛ. Its potential at distance 2R from its centre is:","o":["Vₛ/4","Vₛ/2","2Vₛ","Vₛ"],"a":1,"e":"Outside the sphere V=kQ/r. Doubling r halves the potential.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-35","s":"Physics","c":"Electrostatics","t":"mcq","q":"The work done by an electrostatic field in moving a charge around any closed path is:","o":["positive","negative","zero","path dependent"],"a":2,"e":"Electrostatic fields are conservative, so the line integral of E·dl around a closed loop is zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-36","s":"Physics","c":"Electrostatics","t":"mcq","q":"Which statement about electrostatic field lines is correct?","o":["They can intersect","They form closed loops","They never intersect","They always start and end at the same point"],"a":2,"e":"At any point the electric field has a unique direction, so field lines cannot cross.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-37","s":"Physics","c":"Electrostatics","t":"mcq","q":"If a Gaussian surface encloses no net charge, its total electric flux is:","o":["always zero","always non-zero","infinite","equal to the area"],"a":0,"e":"Gauss’s law gives Φ=Qenclosed/ε₀=0, even if the field is non-zero at parts of the surface.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-38","s":"Physics","c":"Electrostatics","t":"mcq","q":"The total flux through a closed sphere containing charge Q is independent of:","o":["the enclosed charge","the value of ε₀","the sphere’s radius","the sign of Q"],"a":2,"e":"Gauss’s law fixes total flux at Q/ε₀ regardless of the sphere’s radius or shape.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-39","s":"Physics","c":"Electrostatics","t":"mcq","q":"A long uniformly charged wire is surrounded by a coaxial cylindrical Gaussian surface of length L. The enclosed charge is:","o":["λ/L","λL","λ/L²","2πλL"],"a":1,"e":"Linear charge density is charge per unit length, so Qenclosed=λL.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-40","s":"Physics","c":"Electrostatics","t":"mcq","q":"The total flux through that coaxial cylinder around a line charge λ over length L is:","o":["λ/(ε₀L)","λL/ε₀","2πλL/ε₀","zero"],"a":1,"e":"Gauss’s law gives Φ=Qenclosed/ε₀=λL/ε₀.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-41","s":"Physics","c":"Electrostatics","t":"mcq","q":"For a point charge, if the distance from it is reduced to one-third, the electric field magnitude becomes:","o":["three times","six times","nine times","one-ninth"],"a":2,"e":"E∝1/r², so reducing r to r/3 increases E by 3²=9.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-42","s":"Physics","c":"Electrostatics","t":"mcq","q":"A test charge is in a region where electric field is zero everywhere. The potential difference between any two points in that connected region is:","o":["zero","infinite","always positive","always negative"],"a":0,"e":"Since E=−∇V, a region with zero field has constant potential.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-43","s":"Physics","c":"Electrostatics","t":"mcq","q":"An electric dipole is aligned parallel to a uniform electric field. The torque on it is:","o":["pE","pE/2","zero","maximum"],"a":2,"e":"τ=pE sinθ; for θ=0°, torque is zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-44","s":"Physics","c":"Electrostatics","t":"mcq","q":"An electric dipole is aligned antiparallel to a uniform electric field. Its potential energy is:","o":["−pE","zero","+pE","−pE/2"],"a":2,"e":"U=−pE cosθ; for θ=180°, U=+pE, the maximum value.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-45","s":"Physics","c":"Electrostatics","t":"mcq","q":"Two identical positive charges are placed symmetrically about the origin on the x-axis. The electric field at the origin is:","o":["along +x","along −x","zero","perpendicular to x-axis"],"a":2,"e":"The equal fields at the origin are opposite along the x-axis and cancel.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-46","s":"Physics","c":"Electrostatics","t":"mcq","q":"An electron is placed in a uniform electric field directed east. The force on the electron is directed:","o":["east","west","north","zero"],"a":1,"e":"The electron has negative charge, so F=qE is opposite to the field direction.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-47","s":"Physics","c":"Electrostatics","t":"mcq","q":"A charge q is at the centre of a cube. The flux through one face of the cube is:","o":["q/ε₀","q/(2ε₀)","q/(4ε₀)","q/(6ε₀)"],"a":3,"e":"By symmetry the total flux q/ε₀ is shared equally by six faces, giving q/(6ε₀).","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-48","s":"Physics","c":"Electrostatics","t":"mcq","q":"The electric potential at infinity due to an isolated finite point charge is conventionally taken as:","o":["zero","one","infinite","equal to its charge"],"a":0,"e":"For an isolated point charge V=kQ/r, which tends to zero as r tends to infinity.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-49","s":"Physics","c":"Electrostatics","t":"mcq","q":"A dipole is placed perpendicular to a uniform electric field. The magnitude of its torque is:","o":["zero","pE/2","pE","2pE"],"a":2,"e":"At θ=90°, τ=pE sin90°=pE, its maximum magnitude.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"P1-50","s":"Physics","c":"Electrostatics","t":"mcq","q":"A positive charge is placed in an electric field. If the field magnitude is doubled while the charge is unchanged, the force magnitude:","o":["halves","doubles","quadruples","does not change"],"a":1,"e":"F=qE, so doubling E doubles the force.","source":"Original practice","difficulty":"JEE Main · Standard"}],
[{"id":"C1-01","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution contains 0.50 mol of solute in 2.0 L of solution. Its molarity is:","o":["0.10 M","0.25 M","1.0 M","4.0 M"],"a":1,"e":"Molarity = moles of solute / volume of solution in litres =0.50/2.0=0.25 M.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-02","s":"Chemistry","c":"Solutions","t":"mcq","q":"5.85 g of NaCl (molar mass 58.5 g mol⁻¹) is dissolved to make 500 mL solution. The molarity is:","o":["0.10 M","0.20 M","0.50 M","1.0 M"],"a":1,"e":"Moles=5.85/58.5=0.10 mol. Molarity=0.10/0.50=0.20 M.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-03","s":"Chemistry","c":"Solutions","t":"mcq","q":"9.0 g of glucose (M=180 g mol⁻¹) is present in 250 mL of solution. The molarity is:","o":["0.10 M","0.20 M","0.40 M","0.50 M"],"a":1,"e":"Moles of glucose=9/180=0.05 mol. M=0.05/0.25=0.20 M.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-04","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution is prepared by dissolving 0.5 mol solute in 1 kg of solvent. Its molality is:","o":["0.25 m","0.5 m","1.0 m","2.0 m"],"a":1,"e":"Molality is moles of solute per kilogram of solvent, hence 0.5 m.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-05","s":"Chemistry","c":"Solutions","t":"mcq","q":"A mixture contains 2 mol ethanol and 3 mol water. The mole fraction of ethanol is:","o":["0.2","0.4","0.6","0.8"],"a":1,"e":"Total moles=5. Mole fraction of ethanol=2/5=0.4.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-06","s":"Chemistry","c":"Solutions","t":"mcq","q":"2 mg of a solute is present in 1 kg of solution. The concentration is approximately:","o":["0.2 ppm","2 ppm","20 ppm","200 ppm"],"a":1,"e":"For dilute aqueous solutions, 1 mg kg⁻¹ is approximately 1 ppm; therefore 2 mg kg⁻¹≈2 ppm.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-07","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution contains 10 g solute in 90 g solvent. The mass percentage of solute is:","o":["9%","10%","11.1%","90%"],"a":1,"e":"Mass percentage=10/(10+90)×100=10%.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-08","s":"Chemistry","c":"Solutions","t":"mcq","q":"100 mL of a 2.0 M solution is diluted to a final volume of 500 mL. The final molarity is:","o":["0.2 M","0.4 M","1.0 M","4.0 M"],"a":1,"e":"Using M₁V₁=M₂V₂, M₂=(2.0×100)/500=0.40 M.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-09","s":"Chemistry","c":"Solutions","t":"mcq","q":"100 mL of 1.0 M NaCl is mixed with 100 mL of 2.0 M NaCl. Assuming additive volumes, the final molarity is:","o":["1.0 M","1.5 M","2.0 M","3.0 M"],"a":1,"e":"Total moles=0.1+0.2=0.3 mol; total volume=0.2 L. M=0.3/0.2=1.5 M.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-10","s":"Chemistry","c":"Solutions","t":"mcq","q":"The molality of a solution is preferred over molarity in temperature-dependent studies because molality depends on:","o":["volume of solution","mass of solvent","density of solution","volume of solvent"],"a":1,"e":"Molality uses mass of solvent, which does not change with temperature.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-11","s":"Chemistry","c":"Solutions","t":"mcq","q":"For an ideal solution of two volatile liquids A and B, the partial vapour pressure of A is:","o":["pA=xB pA°","pA=xA pA°","pA=pA°/xA","pA=xA/pA°"],"a":1,"e":"Raoult’s law states pA=xA pA°, where xA is the liquid-phase mole fraction.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-12","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution contains a non-volatile solute with mole fraction 0.20. If the pure solvent vapour pressure is 100 kPa, the solution vapour pressure is:","o":["20 kPa","40 kPa","80 kPa","100 kPa"],"a":2,"e":"Solvent mole fraction=0.80. By Raoult’s law p=0.80×100=80 kPa.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-13","s":"Chemistry","c":"Solutions","t":"mcq","q":"For a dilute solution containing a non-volatile solute, the relative lowering of vapour pressure is equal to the:","o":["mole fraction of solvent","mole fraction of solute","molality of solvent","molarity of solute"],"a":1,"e":"For a dilute solution, (p°−p)/p°=xsolute.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-14","s":"Chemistry","c":"Solutions","t":"mcq","q":"An ideal solution is one that obeys Raoult’s law:","o":["only at low temperature","over the entire composition range","only at infinite dilution","only for electrolytes"],"a":1,"e":"An ideal solution obeys Raoult’s law for every composition and has ΔHmix=0 and ΔVmix=0.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-15","s":"Chemistry","c":"Solutions","t":"mcq","q":"For an ideal binary solution, the total vapour pressure is:","o":["xA pA° + xB pB°","pA° + pB°","xA/pA° + xB/pB°","pA°pB°"],"a":0,"e":"The total pressure is the sum of partial pressures: P=xA pA°+xB pB°.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-16","s":"Chemistry","c":"Solutions","t":"mcq","q":"The elevation in boiling point of a dilute solution is given by:","o":["ΔTb=Kf m","ΔTb=Kb m","ΔTb=RT","ΔTb=Kb/m"],"a":1,"e":"For a dilute non-electrolyte solution, ΔTb=Kb m.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-17","s":"Chemistry","c":"Solutions","t":"mcq","q":"The depression in freezing point of a dilute solution is:","o":["ΔTf=Kf m","ΔTf=Kb m","ΔTf=Kf/m","ΔTf=RT"],"a":0,"e":"For a dilute solution, ΔTf=Kf m.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-18","s":"Chemistry","c":"Solutions","t":"mcq","q":"The osmotic pressure of a dilute solution of a non-electrolyte is:","o":["π=CRT","π=C/RT","π=RT/C","π=CR/T"],"a":0,"e":"Van’t Hoff equation for dilute solutions is π=CRT, where C is molar concentration.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-19","s":"Chemistry","c":"Solutions","t":"mcq","q":"At the same temperature, two dilute solutions are isotonic when they have equal:","o":["molar masses","osmotic pressures","boiling points only","densities"],"a":1,"e":"Isotonic solutions have the same osmotic pressure at the same temperature.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-20","s":"Chemistry","c":"Solutions","t":"mcq","q":"A non-electrolyte solution has concentration 0.20 mol L⁻¹ at 300 K. Taking R=0.0821 L atm mol⁻¹ K⁻¹, its osmotic pressure is approximately:","o":["0.49 atm","2.46 atm","4.93 atm","24.6 atm"],"a":2,"e":"π=CRT=0.20×0.0821×300≈4.93 atm.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-21","s":"Chemistry","c":"Solutions","t":"mcq","q":"For complete dissociation of KCl in dilute water, the van’t Hoff factor i is ideally:","o":["1","2","3","4"],"a":1,"e":"KCl dissociates into K⁺ and Cl⁻, giving two particles per formula unit.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-22","s":"Chemistry","c":"Solutions","t":"mcq","q":"For complete dissociation of CaCl₂, the ideal van’t Hoff factor is:","o":["1","2","3","4"],"a":2,"e":"CaCl₂ produces one Ca²⁺ and two Cl⁻ ions, so i=3.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-23","s":"Chemistry","c":"Solutions","t":"mcq","q":"For complete dissociation of AlCl₃, the ideal van’t Hoff factor is:","o":["2","3","4","5"],"a":2,"e":"AlCl₃ produces one Al³⁺ and three Cl⁻ ions, giving four particles.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-24","s":"Chemistry","c":"Solutions","t":"mcq","q":"For glucose dissolved in water, assuming no association or dissociation, the van’t Hoff factor is:","o":["0.5","1","2","3"],"a":1,"e":"Glucose is a non-electrolyte and remains as individual molecules, so i=1.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-25","s":"Chemistry","c":"Solutions","t":"mcq","q":"For dissociation AB → A⁺ + B⁻ with degree of dissociation α, the van’t Hoff factor is:","o":["1−α","1+α","1+2α","2−α"],"a":1,"e":"One particle becomes two; i=1−α+2α=1+α.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-26","s":"Chemistry","c":"Solutions","t":"mcq","q":"For dissociation AB₂ → A²⁺ + 2B⁻ with degree of dissociation 0.5, the van’t Hoff factor is:","o":["1.0","1.5","2.0","2.5"],"a":2,"e":"One formula unit gives three ions. i=1+α(3−1)=1+2(0.5)=2.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-27","s":"Chemistry","c":"Solutions","t":"mcq","q":"Two molecules dimerise: 2A ⇌ A₂. If the degree of association is 0.50, the van’t Hoff factor is:","o":["0.50","0.75","1.00","1.50"],"a":1,"e":"For dimerisation, i=1−α/2=1−0.25=0.75.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-28","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 0.10 molal aqueous solution of a non-electrolyte has Kf=1.86 K kg mol⁻¹. Its freezing point depression is:","o":["0.0186 K","0.186 K","1.86 K","18.6 K"],"a":1,"e":"ΔTf=Kf m=1.86×0.10=0.186 K.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-29","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 0.20 molal solution has Kb=0.52 K kg mol⁻¹ and i=1. The elevation in boiling point is:","o":["0.052 K","0.104 K","0.26 K","0.52 K"],"a":1,"e":"ΔTb=iKb m=1×0.52×0.20=0.104 K.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-30","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution shows a freezing point depression of 0.372 K. If Kf=1.86 K kg mol⁻¹ and i=1, its molality is:","o":["0.1 m","0.2 m","0.5 m","2.0 m"],"a":1,"e":"m=ΔTf/Kf=0.372/1.86=0.20 mol kg⁻¹.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-31","s":"Chemistry","c":"Solutions","t":"mcq","q":"The Henry’s law form for the solubility of a gas in a liquid is commonly written as:","o":["p=KH x","p=x/KH","p=KH/x","p=KH+x"],"a":0,"e":"Henry’s law states that gas partial pressure p is proportional to its mole fraction x in solution: p=KHx.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-32","s":"Chemistry","c":"Solutions","t":"mcq","q":"At constant temperature, if the pressure of a gas above a liquid is doubled, its dilute-solution mole fraction (Henry’s law range) becomes:","o":["half","twice","four times","unchanged"],"a":1,"e":"From p=KHx, with KH constant, doubling p doubles x.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-33","s":"Chemistry","c":"Solutions","t":"mcq","q":"For a solution with positive deviation from Raoult’s law, A–B interactions are generally:","o":["stronger than A–A and B–B","weaker than A–A and B–B","identical to A–A and B–B","ionic"],"a":1,"e":"Positive deviation occurs when unlike interactions are weaker, allowing molecules to escape more easily.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-34","s":"Chemistry","c":"Solutions","t":"mcq","q":"For a solution with negative deviation from Raoult’s law, the A–B interactions are generally:","o":["weaker","stronger","zero","always non-polar"],"a":1,"e":"Stronger unlike interactions lower escaping tendency and produce negative deviation.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-35","s":"Chemistry","c":"Solutions","t":"mcq","q":"A minimum-boiling azeotrope is generally associated with:","o":["negative deviation","positive deviation","ideal behaviour","zero vapour pressure"],"a":1,"e":"Positive deviation raises vapour pressure and can produce a minimum-boiling azeotrope.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-36","s":"Chemistry","c":"Solutions","t":"mcq","q":"A maximum-boiling azeotrope is generally associated with:","o":["positive deviation","negative deviation","ideal behaviour","complete immiscibility"],"a":1,"e":"Negative deviation lowers vapour pressure and can produce a maximum-boiling azeotrope.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-37","s":"Chemistry","c":"Solutions","t":"mcq","q":"Which concentration term is independent of temperature?","o":["Molarity","Molality","Volume percentage","Normality defined per litre"],"a":1,"e":"Molality depends on masses, not volumes, and is therefore temperature independent.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-38","s":"Chemistry","c":"Solutions","t":"mcq","q":"Which concentration term generally changes when solution temperature changes?","o":["Molality","Mole fraction","Molarity","Mass percentage"],"a":2,"e":"Molarity uses solution volume, which can expand or contract with temperature.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-39","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution is prepared by dissolving 1 mol solute in 4 mol solvent. The solute mole fraction is:","o":["0.20","0.25","0.40","0.80"],"a":0,"e":"Total moles=5; solute mole fraction=1/5=0.20.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-40","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 20% by mass solution contains 20 g solute in:","o":["20 g solution","80 g solution","100 g solution","120 g solution"],"a":2,"e":"Mass percentage is grams of solute per 100 g solution, so the total solution mass is 100 g.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-41","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 10% w/w solution has 10 g solute in:","o":["10 g solvent","90 g solvent","100 g solvent","110 g solvent"],"a":1,"e":"A 10% w/w solution has 10 g solute in 100 g solution, hence 90 g solvent.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-42","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 1.0 M solution has volume 2.0 L. The amount of solute present is:","o":["0.5 mol","1 mol","2 mol","4 mol"],"a":2,"e":"Moles=M×V=1.0×2.0=2.0 mol.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-43","s":"Chemistry","c":"Solutions","t":"mcq","q":"A 0.5 m solution contains 0.5 mol solute in:","o":["0.5 kg solution","1.0 kg solvent","0.5 L solvent","1.0 L solution"],"a":1,"e":"Molality is moles per kilogram of solvent, so 0.5 mol corresponds to 1 kg solvent at 0.5 m.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-44","s":"Chemistry","c":"Solutions","t":"mcq","q":"A solution has mole fraction of solute 0.10. The mole fraction of solvent in a binary solution is:","o":["0.10","0.50","0.90","1.10"],"a":2,"e":"In a binary solution, mole fractions sum to one; xsolvent=1−0.10=0.90.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-45","s":"Chemistry","c":"Solutions","t":"mcq","q":"When a non-volatile solute is added to a pure solvent, the vapour pressure of the solvent:","o":["increases","decreases","remains exactly same","becomes zero"],"a":1,"e":"The solvent mole fraction decreases, so Raoult’s law predicts a lower vapour pressure.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-46","s":"Chemistry","c":"Solutions","t":"mcq","q":"Reverse osmosis occurs when the applied pressure on the solution side is:","o":["zero","less than osmotic pressure","greater than osmotic pressure","equal to atmospheric pressure only"],"a":2,"e":"Applying pressure greater than the osmotic pressure drives solvent from solution through the semipermeable membrane toward pure solvent.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-47","s":"Chemistry","c":"Solutions","t":"mcq","q":"In osmosis through a semipermeable membrane, solvent moves spontaneously from:","o":["more concentrated to less concentrated solution","dilute solution to concentrated solution","solute to solvent","higher pressure to lower pressure only"],"a":1,"e":"The solvent passes from the dilute side (higher solvent chemical potential) to the more concentrated side.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-48","s":"Chemistry","c":"Solutions","t":"mcq","q":"The boiling point of a solution containing a non-volatile solute is generally:","o":["lower than pure solvent","higher than pure solvent","always equal to pure solvent","independent of concentration"],"a":1,"e":"The solute lowers vapour pressure, so a higher temperature is needed for the solution vapour pressure to reach external pressure.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-49","s":"Chemistry","c":"Solutions","t":"mcq","q":"For a dilute solution, the colligative property that is especially useful for determining molar masses of macromolecules is:","o":["osmotic pressure","colour","viscosity only","surface tension only"],"a":0,"e":"Osmotic pressure can be measured at low concentrations and room temperature, making it useful for high molar-mass solutes.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"C1-50","s":"Chemistry","c":"Solutions","t":"mcq","q":"For a fixed mass of solute and solvent, the molality of the solution is:","o":["changed by changing temperature alone","unchanged by changing temperature alone","doubled on heating","halved on cooling"],"a":1,"e":"Molality depends on the masses of solute and solvent, which remain unchanged on heating or cooling.","source":"Original practice","difficulty":"JEE Main · Standard"}],
[{"id":"M1-01","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A has 2 rows and 3 columns, its order is:","o":["3×2","2×3","2×2","3×3"],"a":1,"e":"Matrix order is written as number of rows × number of columns.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-02","s":"Mathematics","c":"Matrices","t":"mcq","q":"A matrix with 3 rows and 1 column is called a:","o":["row matrix","square matrix","column matrix","zero matrix"],"a":2,"e":"A matrix with exactly one column is a column matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-03","s":"Mathematics","c":"Matrices","t":"mcq","q":"Two matrices can be equal only if they have:","o":["equal determinants","same order and equal corresponding entries","same trace only","same number of non-zero entries"],"a":1,"e":"Matrix equality requires the same dimensions and equality of every corresponding element.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-04","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is 2×3 and B is 3×4, the order of AB is:","o":["2×4","3×3","4×2","not defined"],"a":0,"e":"For AB, inner dimensions 3 and 3 match; the product has the outer dimensions 2×4.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-05","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is 2×3 and B is 2×3, the product AB is:","o":["always 2×3","always 3×2","not defined","always 2×2"],"a":2,"e":"AB requires the number of columns of A (3) to equal the number of rows of B (2), which is false.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-06","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is 3×2 and B is 2×1, the order of AB is:","o":["3×1","2×2","1×3","not defined"],"a":0,"e":"The inner dimensions are both 2; the resulting order is 3×1.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-07","s":"Mathematics","c":"Matrices","t":"mcq","q":"For matrices of compatible orders, matrix multiplication is generally:","o":["commutative","not commutative","always zero","always symmetric"],"a":1,"e":"In general AB≠BA, even when both products are defined.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-08","s":"Mathematics","c":"Matrices","t":"mcq","q":"For compatible matrices, which distributive law is valid?","o":["A(B+C)=AB+AC","A(B+C)=BA+CA","(A+B)C=AC+BC only if A=B","A(B+C)=ABC"],"a":0,"e":"Matrix multiplication distributes over addition: A(B+C)=AB+AC when dimensions are compatible.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-09","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a matrix, the transpose of A is obtained by:","o":["changing every sign","interchanging rows and columns","reversing only the first row","taking reciprocals"],"a":1,"e":"The transpose is formed by interchanging rows and columns.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-10","s":"Mathematics","c":"Matrices","t":"mcq","q":"For any matrix A, (Aᵀ)ᵀ equals:","o":["−A","A⁻¹","A","I"],"a":2,"e":"Taking the transpose twice restores the original matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-11","s":"Mathematics","c":"Matrices","t":"mcq","q":"For compatible matrices, (AB)ᵀ equals:","o":["AᵀBᵀ","BᵀAᵀ","AB","BA"],"a":1,"e":"The transpose of a product reverses the order: (AB)ᵀ=BᵀAᵀ.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-12","s":"Mathematics","c":"Matrices","t":"mcq","q":"A square matrix A is symmetric if:","o":["Aᵀ=A","Aᵀ=−A","A²=I","A⁻¹=A"],"a":0,"e":"A symmetric matrix is equal to its transpose.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-13","s":"Mathematics","c":"Matrices","t":"mcq","q":"A square matrix A is skew-symmetric if:","o":["Aᵀ=A","Aᵀ=−A","A²=A","A=I"],"a":1,"e":"By definition, a skew-symmetric matrix satisfies Aᵀ=−A.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-14","s":"Mathematics","c":"Matrices","t":"mcq","q":"Every diagonal entry of a real skew-symmetric matrix is:","o":["1","−1","zero","arbitrary positive"],"a":2,"e":"For a diagonal entry aᵢᵢ, skew symmetry gives aᵢᵢ=−aᵢᵢ, so it must be zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-15","s":"Mathematics","c":"Matrices","t":"mcq","q":"The transpose of a row matrix is a:","o":["square matrix","column matrix","diagonal matrix","zero matrix"],"a":1,"e":"Transposition interchanges rows and columns, turning a row matrix into a column matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-16","s":"Mathematics","c":"Matrices","t":"mcq","q":"The additive identity for matrices of a fixed order is the:","o":["identity matrix","zero matrix","diagonal matrix","inverse matrix"],"a":1,"e":"Adding the zero matrix leaves every matrix unchanged.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-17","s":"Mathematics","c":"Matrices","t":"mcq","q":"For any square matrix A of order n, AIₙ is equal to:","o":["Iₙ","0","A","Aᵀ"],"a":2,"e":"The identity matrix is the multiplicative identity: AI=IA=A.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-18","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a 2×2 matrix and k is a scalar, the order of kA is:","o":["1×1","2×2","2×1","depends on k"],"a":1,"e":"Scalar multiplication changes entries, not the dimensions of a matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-19","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A=[[1,2],[3,4]], then 2A is:","o":["[[2,4],[6,8]]","[[1,4],[3,8]]","[[2,2],[6,4]]","[[1,2],[6,8]]"],"a":0,"e":"Multiply each entry by 2.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-20","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A=[[1,2],[3,4]] and B=[[4,3],[2,1]], then A+B is:","o":["[[5,5],[5,5]]","[[4,6],[6,4]]","[[3,1],[1,3]]","[[5,1],[5,5]]"],"a":0,"e":"Add corresponding entries: [[1+4,2+3],[3+2,4+1]]=[[5,5],[5,5]].","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-21","s":"Mathematics","c":"Matrices","t":"mcq","q":"For A=[[1,2],[0,1]], A² is:","o":["[[1,2],[0,1]]","[[1,4],[0,1]]","[[1,0],[2,1]]","[[2,2],[0,2]]"],"a":1,"e":"Multiplying A by itself gives [[1,4],[0,1]].","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-22","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A=[[1,0],[2,1]] and B=[[3,1],[0,2]], the (1,2) entry of AB is:","o":["0","1","2","3"],"a":1,"e":"Row 1 of A dotted with column 2 of B gives 1×1+0×2=1.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-23","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is 2×3, the order of Aᵀ is:","o":["2×3","3×2","2×2","3×3"],"a":1,"e":"Transpose interchanges the dimensions, so Aᵀ is 3×2.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-24","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A and B are symmetric matrices of the same order, A+B is:","o":["always symmetric","always skew-symmetric","never defined","always zero"],"a":0,"e":"(A+B)ᵀ=Aᵀ+Bᵀ=A+B, so the sum is symmetric.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-25","s":"Mathematics","c":"Matrices","t":"mcq","q":"The product of two symmetric matrices A and B is symmetric when:","o":["AB=BA","AB=0 only","A=Bᵀ only","always"],"a":0,"e":"(AB)ᵀ=BᵀAᵀ=BA. For AB to be symmetric, this must equal AB, so A and B must commute.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-26","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is skew-symmetric, then A² is:","o":["always skew-symmetric","symmetric","always identity","always zero"],"a":1,"e":"(A²)ᵀ=(Aᵀ)²=(−A)²=A²; hence A² is symmetric.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-27","s":"Mathematics","c":"Matrices","t":"mcq","q":"A square matrix A is invertible if and only if:","o":["det(A)=0","det(A)≠0","A is symmetric","A has a zero row"],"a":1,"e":"A square matrix is nonsingular and has an inverse precisely when its determinant is non-zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-28","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible, then AA⁻¹ equals:","o":["A","A⁻¹","I","0"],"a":2,"e":"The inverse is defined by AA⁻¹=A⁻¹A=I.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-29","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A⁻¹ exists, then (A⁻¹)⁻¹ is:","o":["A","−A","Aᵀ","I"],"a":0,"e":"The inverse of the inverse returns the original matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-30","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A and B are invertible square matrices of the same order, (AB)⁻¹ is:","o":["A⁻¹B⁻¹","B⁻¹A⁻¹","AB","BA"],"a":1,"e":"The inverse of a product reverses order: (AB)⁻¹=B⁻¹A⁻¹.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-31","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible, the inverse of Aᵀ is:","o":["(A⁻¹)ᵀ","A⁻¹","−Aᵀ","A"],"a":0,"e":"Using (AB)ᵀ and the identity, (Aᵀ)⁻¹=(A⁻¹)ᵀ.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-32","s":"Mathematics","c":"Matrices","t":"mcq","q":"For A=[[a,b],[c,d]], its inverse (when ad−bc≠0) is:","o":["1/(ad−bc) [[d,−b],[−c,a]]","1/(ad+bc) [[d,b],[c,a]]","[[d,−b],[−c,a]]","1/(ad−bc) [[a,−c],[−b,d]]"],"a":0,"e":"The 2×2 inverse is adj(A)/det(A), with adj(A)=[[d,−b],[−c,a]].","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-33","s":"Mathematics","c":"Matrices","t":"mcq","q":"The inverse of [[2,0],[0,4]] is:","o":["[[1/2,0],[0,1/4]]","[[2,0],[0,4]]","[[4,0],[0,2]]","[[0,1/2],[1/4,0]]"],"a":0,"e":"The inverse of a nonsingular diagonal matrix has reciprocal diagonal entries.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-34","s":"Mathematics","c":"Matrices","t":"mcq","q":"The inverse of [[1,0],[0,1]] is:","o":["zero matrix","identity matrix","negative identity","not defined"],"a":1,"e":"The identity matrix is its own inverse.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-35","s":"Mathematics","c":"Matrices","t":"mcq","q":"The matrix [[1,2],[2,4]] has:","o":["an inverse","no inverse","inverse equal to itself","inverse equal to zero"],"a":1,"e":"Its determinant is 1×4−2×2=0, so it is singular and has no inverse.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-36","s":"Mathematics","c":"Matrices","t":"mcq","q":"If a square matrix has two identical rows, it is:","o":["invertible","singular","identity","skew-symmetric"],"a":1,"e":"Identical rows make the rows linearly dependent, so the determinant is zero and no inverse exists.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-37","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible and AX=B, then X is:","o":["AB⁻¹","A⁻¹B","BA⁻¹","A+B"],"a":1,"e":"Multiplying AX=B on the left by A⁻¹ gives X=A⁻¹B.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-38","s":"Mathematics","c":"Matrices","t":"mcq","q":"If XA=B and A is invertible, then X is:","o":["A⁻¹B","BA⁻¹","AB⁻¹","B⁻¹A"],"a":1,"e":"Multiplying XA=B on the right by A⁻¹ gives X=BA⁻¹.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-39","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible, the solution of AX=I is:","o":["A","Aᵀ","A⁻¹","zero matrix"],"a":2,"e":"By definition, A⁻¹A=AA⁻¹=I; the solution is X=A⁻¹.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-40","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a 3×3 matrix, the order of A⁻¹ (if it exists) is:","o":["3×1","1×3","3×3","9×1"],"a":2,"e":"A matrix inverse has the same square order as the original matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-41","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a nonsingular matrix, then (kA)⁻¹ for k≠0 equals:","o":["kA⁻¹","A⁻¹/k","k⁻¹A","A/k²"],"a":1,"e":"(kA)(A⁻¹/k)=I, so (kA)⁻¹=(1/k)A⁻¹.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-42","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible and A²=I, then A⁻¹ is:","o":["A","−A","I","0"],"a":0,"e":"From A²=I, A·A=I, so A is its own inverse.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-43","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a square matrix and Aᵀ=A, then A is:","o":["skew-symmetric","symmetric","orthogonal necessarily","singular necessarily"],"a":1,"e":"This is exactly the definition of a symmetric matrix.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-44","s":"Mathematics","c":"Matrices","t":"mcq","q":"If Aᵀ=−A for a real square matrix, then the trace of A is:","o":["1","−1","zero","not defined"],"a":2,"e":"All diagonal entries of a skew-symmetric matrix are zero, so its trace is zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-45","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is an invertible symmetric matrix, then A⁻¹ is:","o":["symmetric","skew-symmetric","never symmetric","zero"],"a":0,"e":"(A⁻¹)ᵀ=(Aᵀ)⁻¹=A⁻¹, so its inverse is symmetric.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-46","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is invertible and AB=AC, then:","o":["B=C","A=B","B=0","C=0"],"a":0,"e":"Left-multiply both sides by A⁻¹ to obtain B=C.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-47","s":"Mathematics","c":"Matrices","t":"mcq","q":"For a square matrix A, if A²=A, then A is called:","o":["nilpotent","idempotent","orthogonal","skew-symmetric"],"a":1,"e":"A matrix satisfying A²=A is idempotent.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-48","s":"Mathematics","c":"Matrices","t":"mcq","q":"For a square matrix A, if A²=0, then A is called:","o":["idempotent","nilpotent","symmetric","identity"],"a":1,"e":"A matrix whose positive integer power is zero is nilpotent; here the square is zero.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-49","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is an invertible matrix, the equation A X A⁻¹=I has solution:","o":["X=I","X=A","X=A⁻¹","X=0"],"a":0,"e":"Multiply by A⁻¹ on the left and A on the right: X=I.","source":"Original practice","difficulty":"JEE Main · Standard"},{"id":"M1-50","s":"Mathematics","c":"Matrices","t":"mcq","q":"If A is a square matrix and A+Aᵀ is formed, the resulting matrix is always:","o":["skew-symmetric","symmetric","zero","singular"],"a":1,"e":"(A+Aᵀ)ᵀ=Aᵀ+A=A+Aᵀ, hence it is symmetric.","source":"Original practice","difficulty":"JEE Main · Standard"}]
];
JEE_DAY1_TOPIC_PACK.forEach(q=>{JEE_QUESTIONS.push(q);JEE_BANK_COUNTS[q.c]=(JEE_BANK_COUNTS[q.c]||0)+1;});

function isCompetitiveQuestion(q){return !!q.difficulty && (q.difficulty.includes('Tough')||q.difficulty.includes('Challenge'));}

